ch02.main:
address {
  street: "21 2nd Street"
  city: "New York"
  state: NY
}
database {
  primary { host: db1 port: 5432 }
  replica { host: db2 port: 5432 }
}
tags: [ logging metrics tracing ]
users: [
  { name: alice role: admin }
  { name: bob role: user }
]

ch03.main:
@base {
  region: cn-north-1
  timeout: 30
}
service auth { &base port: 7100 name: auth-svc }
service billing { &base port: 7200 name: billing-svc }

ch05.main:
@contract Server strict {
  name: str
  port: int min 1024 max 65535
  region: str
}
@is Server
name: 大厅
port: 25565
region: ap-east-1

ch06.main:
secrets {
  apiKey: $env.RESEND_API_KEY
  dbPassword: $env.DB_PASSWORD
}
banner: "SML \u{1F680} 上线"

ch07.main:
@contract User {
  id: str
  email: str
  role: enum(user, admin, owner) default user
}
@is User
id: u_1
email: a@b.c

ch08.main:
@contract Service loose {
  name: str
  port: int default 8080 min 1 max 65535
  debug: bool default false
}
@base {
  region: cn-north-1
  timeout: 30
}

@is Service
name: gateway
port: 9090
debug: true

peers: [ auth billing ]
service auth { &base port: 7100 name: auth-svc }
service billing { &base port: 7200 name: billing-svc }

database: {
  url: $env.DATABASE_URL
  pool: { min: 2 max: 16 }
}
features: [ logging metrics tracing ]

ch09.main:
@contract Endpoint {
  host: str
  port: int
}
@contract Service {
  name: str
  main: Endpoint
  peers: array[Endpoint] ?
}
@is Service
name: gateway
main: { host: localhost port: 8080 }
peers: [ { host: db port: 5432 } ]

files.auth.sml:
@contract Module { name: str }
@is Module
name: auth

files.billing.sml:
@contract Module { name: str }
@is Module
name: billing
